// Normalização de payload recebido de instâncias do WhatsApp (Evolution API, Z-API, Baileys, Webhooks)
const body = $input.first().json.body || $input.first().json;

// Extrai telefone, nome e mensagem com fallbacks robustos
const senderPhone = (body.phone || body.remoteJid || body.sender || body.from || '5511999999999').replace(/\D/g, '');
const pushName = body.pushName || body.name || body.senderName || 'Paciente';
const messageText = (body.message?.conversation || body.message?.extendedTextMessage?.text || body.text || body.body || '').trim();

return [{
  json: {
    senderPhone,
    pushName,
    messageText,
    lowerText: messageText.toLowerCase(),
    receivedAt: new Date().toISOString()
  }
}];

// TRIAGEM ÉTICA E DETECÇÃO DE CRISE SEVERA (RESOLUÇÃO CFP E CÓDIGO DE ÉTICA)
// Softwares e bots NUNCA devem fingir ser psicólogos ou atender crises suicidas
const text = $input.first().json.lowerText;
const phone = $input.first().json.senderPhone;
const name = $input.first().json.pushName;

const crisisKeywords = [
  'suicidio', 'suicídio', 'me matar', 'acabar com a vida', 'acabar com tudo',
  'tirar minha vida', 'morrer', 'quero sumir', 'desespero', 'nao aguento mais',
  'não aguento mais', 'automutilacao', 'automutilação', 'desesperado', 'desesperada'
];

const isCrisis = crisisKeywords.some(keyword => text.includes(keyword));

let intent = 'duvidas_gerais';

if (isCrisis) {
  intent = 'CRISE_EMERGENCIA';
} else if (text === '1' || text.includes('confirmar') || text.includes('sim') || text.includes('presenca')) {
  intent = 'CONFIRMAR_PRESENCA';
} else if (text === '2' || text.includes('remarcar') || text.includes('mudar horario') || text.includes('mudar horário')) {
  intent = 'REMARCAR';
} else if (text === '3' || text.includes('pix') || text.includes('pagar') || text.includes('comprovante') || text.includes('valor')) {
  intent = 'PAGAMENTO_PIX';
} else if (text.includes('agendar') || text.includes('consulta') || text.includes('sessao') || text.includes('sessão') || text.includes('horario') || text.includes('horário')) {
  intent = 'NOVO_AGENDAMENTO';
} else if (text.includes('humano') || text.includes('psicologa') || text.includes('psicóloga') || text.includes('secretaria') || text.includes('atendente')) {
  intent = 'FALAR_HUMANO';
}

return [{
  json: {
    ...$input.first().json,
    isCrisis,
    intent
  }
}];

